inline void score_service_dt(double* input, double* output) {
 output[0]=output[1]=output[2]=0;
 for (int root: scada_common_dt::roots) {
  int i=root;
  while(scada_common_dt::nodes[i].left>=0) {
   const auto& n=scada_common_dt::nodes[i];
   i=static_cast<float>(input[n.feature])<=n.threshold?n.left:n.right;
  }
  for(int c=0;c<3;c++) output[c]+=scada_common_dt::nodes[i].p[c];
 }
 for(int c=0;c<3;c++) output[c]/=1.0;
}
